head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > M > setDisplayFormatter]<br/>컴포넌트의 displayFormatter 속성을 설정합니다.",
    "validation" : [
        "formatter(필수) 파라미터로 표시되는 입력값의 포맷을 변환할 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수의 파라미터로 컴포넌트에 입력된 실제값이 전달됩니다.",
        "사용자 정의 함수의 반환값이 컴포넌트에 표시되는 입력값으로 적용됩니다.",
        "displayFormatter 를 설정하면 displayformat 속성은 무시됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {
    // searchbox 는 wrapper DIV 안의 inner input element 에 값이 들어감 → inner input.value 조회
    let rtn;
    if (target.render.tagName === "INPUT") {
        rtn = target.render.value;
    } else {
        let inputEl = target.render.querySelector("input");
        rtn = inputEl ? inputEl.value : '';
    }
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}



scwin.get_displayFormat = function(target) {
    let rtn = '';
    rtn = target.getDisplayFormat();

     wf_body_bottom.getObj("scwin").setReturnValue("getDisplayFormat : " + rtn);
}



 // 사용자 정의 함수
 scwin.fn_dpformatter = function(val) {
    return "language -> " + val;
 };



// target1
scwin.btn_setDisplayFormatter1_onclick = function (e) {
    target1.setDisplayFormatter("scwin.fn_dpformatter");
    target1.setValue("langkoKR");
    // target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

// target2
scwin.btn_setDisplayFormatter2_onclick = function (e) {
    target2.setDisplayFormatter("scwin.fn_dpformatter");
    target2.setValue("langkoKR");
    // target1.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
}

scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i < 3; i ++)
        eval("scwin.btn_setDisplayFormatter"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 3; i ++)
        eval("scwin.btn_getText"+i+"_onclick()");
};
